import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n, p = map(int, data[0].split())

    # 处理后续的每一行
    for i in range(1, len(data)):
        line = data[i].strip()
        if not line:
            continue

        # 去掉首尾的 '|'
        inner = line[1:-1]
        # 按 '|' 分割得到每个节
        sections = inner.split('|')
        result_parts = []

        for sec in sections:
            L = len(sec)
            if p >= L:
                # 延迟长度大于等于节长度，全部为下划线
                result_parts.append('_' * L)
            else:
                # 前面 p 个下划线，后面接原节前 L-p 个字符
                result_parts.append('_' * p + sec[:L - p])

        # 组装输出
        print('|' + '|'.join(result_parts) + '|')

if __name__ == "__main__":
    main()
```

